package com.toabea.closet.config;
import com.toabea.closet.auth.*; import org.springframework.context.annotation.*; import org.springframework.stereotype.Component; import org.springframework.http.HttpHeaders; import org.springframework.security.authentication.*; import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration; import org.springframework.security.config.annotation.web.builders.HttpSecurity; import org.springframework.security.config.http.SessionCreationPolicy; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.security.web.*; import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter; import org.springframework.web.filter.OncePerRequestFilter; import jakarta.servlet.*; import jakarta.servlet.http.*; import java.io.IOException;
@Configuration public class SecurityConfig { @Bean PasswordEncoder passwordEncoder(){return new BCryptPasswordEncoder(12);} @Bean AuthenticationManager authenticationManager(AuthenticationConfiguration c)throws Exception{return c.getAuthenticationManager();} @Bean SecurityFilterChain filterChain(HttpSecurity http,JwtFilter filter,@org.springframework.beans.factory.annotation.Qualifier("corsConfigurationSource") org.springframework.web.cors.CorsConfigurationSource corsSource)throws Exception{return http.csrf(c->c.disable()).cors(c->c.configurationSource(corsSource)).headers(h->h.httpStrictTransportSecurity(hsts->hsts.includeSubDomains(true).maxAgeInSeconds(31536000))).sessionManagement(s->s.sessionCreationPolicy(SessionCreationPolicy.STATELESS)).authorizeHttpRequests(a->a.requestMatchers("/error","/api/auth/login","/actuator/health","/api/products/public","/api/categories/public","/api/config/public","/api/payments/paystack/**").permitAll().requestMatchers(org.springframework.http.HttpMethod.POST,"/api/orders").permitAll().requestMatchers(org.springframework.http.HttpMethod.POST,"/api/orders/*/cancel").permitAll().anyRequest().hasRole("ADMIN")).addFilterBefore(filter,UsernamePasswordAuthenticationFilter.class).build();} }
@Component class JwtFilter extends OncePerRequestFilter { private final JwtService jwt; private final AdminUserDetailsService users; JwtFilter(JwtService jwt,AdminUserDetailsService users){this.jwt=jwt;this.users=users;} protected void doFilterInternal(HttpServletRequest r,HttpServletResponse s,FilterChain c)throws ServletException,IOException{String h=r.getHeader(HttpHeaders.AUTHORIZATION); if(h!=null&&h.startsWith("Bearer "))try{var d=users.loadUserByUsername(jwt.subject(h.substring(7))); var a=new UsernamePasswordAuthenticationToken(d,null,d.getAuthorities()); org.springframework.security.core.context.SecurityContextHolder.getContext().setAuthentication(a);}catch(Exception ignored){} c.doFilter(r,s);} }
